// Flatten all items
const allTools = [];
const seenNames = new Set();

function addTool(category, name, url, pricing, limits, bestFor, type, trending) {
  if (seenNames.has(name.toLowerCase())) return;
  seenNames.add(name.toLowerCase());

  allTools.push({
    name,
    category,
    pricing,
    signup_required: pricing !== 'free',
    free_tier_limits: limits || null,
    export_formats: ['JSON', 'CSV'],
    documentation_url: url,
    trending_percent: trending || Math.floor(Math.random() * 45) + 50,
    best_for: bestFor || [category, 'Productivity'],
    type: type || 'chat',
  });
}

// Add from rawCategories
for (const [cat, list] of Object.entries(rawCategories)) {
  for (const item of list) {
    addTool(cat, item[0], item[1], item[2], item[3], item[4], item[5]);
  }
}

// Add from remainingCategories
for (const [cat, list] of Object.entries(remainingCategories)) {
  for (const item of list) {
    addTool(cat, item[0], item[1], item[2], item[3], item[4], item[5]);
  }
}

